import os
import random
import string
from typing import List

def _weighted_choice(choices):
    total = sum(w for _, w in choices)
    r = random.uniform(0, total)
    upto = 0
    for val, w in choices:
        if upto + w >= r:
            return val
        upto += w
    return choices[-1][0]

def _random_filename(base_names: List[str], exts: List[str]) -> str:
    # Build a base filename with optional special chars and length variations
    name_style = _weighted_choice([
        ("simple", 5),
        ("dotted", 2),
        ("spaces", 2),
        ("unicode", 1),
        ("long", 1),
    ])

    def rand_token(alphabet, min_len, max_len):
        L = random.randint(min_len, max_len)
        return "".join(random.choice(alphabet) for _ in range(L))

    ascii_alnum = string.ascii_letters + string.digits
    ascii_safe = ascii_alnum + "-_"

    if name_style == "simple":
        base = random.choice(base_names)
    elif name_style == "dotted":
        base = rand_token(ascii_safe, 1, 6) + "." + rand_token(ascii_safe, 1, 6)
    elif name_style == "spaces":
        base = rand_token(ascii_alnum, 1, 4) + " " + rand_token(ascii_alnum, 1, 4)
    elif name_style == "unicode":
        # Include a few common safe unicode characters
        unicode_chars = "αβγδεζηθλμνξопрстуф汉字日本語äöüßñçΩΔ"
        base = rand_token(ascii_alnum + unicode_chars, 3, 10)
    else:  # long
        base = rand_token(ascii_safe, 20, 40)

    ext_choice = _weighted_choice([
        ("", 3),
        (random.choice(exts), 5),
    ])

    return base + ext_choice

def _random_dir_components() -> List[str]:
    components = []
    depth = _weighted_choice([
        (0, 4), (1, 5), (2, 4), (3, 3), (4, 2)
    ])
    dir_alphabet = string.ascii_letters + string.digits + "-_"
    special_names = ["tmp", "var", "dev", "home", "mnt", "proc", "run", "etc", "usr", "opt"]
    for _ in range(depth):
        style = _weighted_choice([
            ("named", 5),
            ("rand", 3),
            ("dot", 1),
        ])
        if style == "named":
            components.append(random.choice(special_names))
        elif style == "dot":
            components.append(random.choice([".", ".."]))
        else:
            L = random.randint(1, 10)
            components.append("".join(random.choice(dir_alphabet) for _ in range(L)))
    return components

def _with_prefix(path: str) -> str:
    # Choose absolute or relative, and optionally add Windows-like elements to diversify
    kind = _weighted_choice([
        ("posix_abs", 6),
        ("posix_rel", 3),
        ("posix_tilde", 1),
    ])

    if kind == "posix_abs":
        return "/" + path.lstrip("/")
    elif kind == "posix_tilde":
        return "~" + ("/" + path.lstrip("/"))
    else:
        return path.lstrip("/")

def _sprinkle_trailing(path: str) -> str:
    # Sometimes add trailing slash, dot, or space to exercise fopen handling
    choice = _weighted_choice([
        ("none", 8),
        ("slash", 1),
        ("dot", 1),
    ])
    if choice == "slash":
        return path + "/"
    if choice == "dot":
        return path + "."
    return path

def _build_path() -> str:
    base_names = [
        "report", "log", "out", "dump", "trace", "profile", "stats",
        "data", "info", "result", "mem", "tree"
    ]
    exts = [".txt", ".log", ".out", ".dat"]

    # Generate directory components and a filename
    dirs = _random_dir_components()
    fname = _random_filename(base_names, exts)

    # Join POSIX-style
    rel = "/".join([c for c in dirs if c != ""] + [fname]) if dirs else fname
    full = _with_prefix(rel)
    full = _sprinkle_trailing(full)

    # Ensure non-empty and capped length
    if not full:
        full = "report.log"
    return full[:4000]

def generate(seed: int) -> bytes:
    """
    Generate a bytes buffer representing a filesystem path for use with fopen(path, "wb").
    The path is POSIX-friendly and aims to be valid and writable in typical fuzzing sandboxes.
    The function is deterministic given the seed but introduces variety across different seeds.
    """
    random.seed(seed)

    # Prefer writable temp-like locations to increase fopen success rate
    preferred_roots = ["/tmp", "/var/tmp", "/dev/shm"]
    root = _weighted_choice([(r, 5) for r in preferred_roots] + [("", 3)])

    # Optionally add a subdirectory hierarchy under the chosen root
    subdirs = _random_dir_components()
    # Ensure at least one path segment before filename if using a root
    if root:
        parts = [p for p in [root] + subdirs if p not in ("", "/")]
        base_path = "/".join(parts)
    else:
        base_path = ""  # relative or absolute decided in _build_path

    leaf = _random_filename(
        ["report", "log", "fuzz", "talloc", "mem", "tree", "stats", "out", "result"],
        [".log", ".txt", ".out", ".dat"]
    )

    if base_path:
        candidate = base_path.rstrip("/") + "/" + leaf
    else:
        candidate = _build_path()

    # Final safety: strip NULs and ensure reasonable length
    candidate = candidate.replace("\x00", "_")[:4096]

    return candidate.encode("utf-8", errors="ignore")
